import numpy as np

# Define the sequence
qr = [1,2,3,4,6,8,9,12,13,16,18]
x = np.array([1 if i==0 or i in qr else -1 for i in range(23)])
print(x)
print('Sum:', np.sum(x))

def autocorr(k):
    return np.sum(x * np.roll(x, -k))

for k in range(1,12):
    print(k, autocorr(k))

